package com.pharmapack.qms.deviation; import com.pharmapack.qms.audit.AuditTrailService; import com.pharmapack.qms.batch.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api/deviations") public class DeviationController { final DeviationRepository dr; final BatchRepository br; final AuditTrailService at; public DeviationController(DeviationRepository d,BatchRepository b,AuditTrailService a){dr=d;br=b;at=a;} @GetMapping public List<DeviationResponse> list(){return dr.findAll().stream().map(this::dto).toList();} public record Create(String deviationNumber,Long batchId,String title,String description,String severity,Long openedBy){}
 @PostMapping @ResponseStatus(HttpStatus.CREATED) public DeviationResponse create(@RequestBody Create x){if(dr.existsByDeviationNumber(x.deviationNumber()))throw new IllegalArgumentException("Duplicate deviation number");Deviation d=new Deviation();d.setDeviationNumber(x.deviationNumber());if(x.batchId()!=null)d.setBatch(br.findById(x.batchId()).orElseThrow(()->new IllegalArgumentException("Batch not found")));d.setTitle(x.title());d.setDescription(x.description());d.setSeverity(x.severity());d.setOpenedBy(x.openedBy());d.setOpenedAt(LocalDateTime.now());Deviation saved=dr.save(d);at.log("CREATE","Deviation",saved.getId(),"severity",null,saved.getSeverity());return dto(dr.findById(saved.getId()).orElseThrow());}
 DeviationResponse dto(Deviation d){var b=d.getBatch();return new DeviationResponse(d.getId(),d.getDeviationNumber(),b==null?null:b.getId(),b==null?null:b.getBatchNumber(),b==null?null:b.getProduct().getProductCode(),b==null?null:b.getProduct().getProductName(),d.getTitle(),d.getDescription(),d.getSeverity(),d.getStatus(),d.getOpenedBy(),d.getOpenedAt(),d.getClosedAt());}
}
